<?php declare(strict_types=1); namespace App\Http\Requests\Pmbm; use Illuminate\Foundation\Http\FormRequest; class StoreApplicantRequest extends FormRequest { public function authorize():bool{return true;} public function rules():array{return ['academic_year_id'=>'required|exists:academic_years,id','full_name'=>'required|string|max:200','nickname'=>'nullable|string|max:100','nik'=>'nullable|string|max:30','nisn'=>'nullable|string|max:30','gender'=>'required|in:male,female','birth_place'=>'required|string|max:150','birth_date'=>'required|date|before:today','parent_email'=>'nullable|email|max:255','parent_phone'=>'required|string|max:30','father_name'=>'nullable|string|max:200','mother_name'=>'nullable|string|max:200','guardian_name'=>'nullable|string|max:200','address'=>'required|string|max:1500','special_needs'=>'nullable|string|max:500','consent'=>'accepted','documents.*'=>'nullable|file|mimes:jpg,jpeg,png,pdf|max:5120'];} public function messages():array{return ['consent.accepted'=>'Pernyataan kebenaran data wajib disetujui.','documents.*.mimes'=>'Lampiran harus JPG, JPEG, PNG, atau PDF.','documents.*.max'=>'Ukuran lampiran maksimal 5 MB.'];} }
